0644\\u0631\\u0648\\u0627\\u0626\\u062d \\u0627\\u0644\\u062a\\u064a \\u062a\\u0641\\u0631\\u0636 \\u062d\\u0636\\u0648\\u0631\\u0647\\u0627 \\u0628\\u0642\\u0648\\u0629 \\u0648\\u062a\\u062a\\u0631\\u0643 \\u0623\\u062b\\u0631\\u0627\\u064b \\u0644\\u0627 \\u064a\\u064f\\u0646\\u0633\\u0649.<br><br>\\u0625\\u0644\\u064a\\u0643 \\u0634\\u0631\\u062d \\u0645\\u0641\\u0635\\u0644 \\u0644\\u0647\\u0630\\u0627 \\u0627\\u0644\\u0639\\u0637\\u0631 \\u0627\\u0644\\u0630\\u064a \\u064a\\u062c\\u0645\\u0639 \\u0628\\u064a\\u0646 \\u0627\\u0644\\u062c\\u0631\\u0623\\u0629 \\u0648\\u0627\\u0644\\u0641\\u062e\\u0627\\u0645\\u0629:<br><br>### 1. \\u0627\\u0644\\u0647\\u0631\\u0645 \\u0627\\u0644\\u0639\\u0637\\u0631\\u064a (\\u0627\\u0644\\u0646\\u0648\\u062a\\u0627\\u062a)<br>\\u064a\\u062a\\u0645\\u064a\\u0632 \\u0627\\u0644\\u0639\\u0637\\u0631 \\u0628\\u062a\\u0648\\u0644\\u064a\\u0641\\u0629 \\u0639\\u0645\\u064a\\u0642\\u0629 \\u0648\\u0645\\u0631\\u0643\\u0632\\u0629:<br>* \\u0627\\u0644\\u0627\\u0641\\u062a\\u062a\\u0627\\u062d\\u064a\\u0629: \\u062a\\u0628\\u062f\\u0623 \\u0628\\u0646\\u0641\\u062d\\u0627\\u062a \\u0642\\u0648\\u064a\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0647\\u064a\\u0644 \\u0648\\u0627\\u0644\\u0632\\u0639\\u0641\\u0631\\u0627\\u0646 \\u0645\\u0639 \\u0644\\u0645\\u0633\\u0629 \\u0645\\u0646 \\u062c\\u0648\\u0632\\u0629 \\u0627\\u0644\\u0637\\u064a\\u0628\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0639\\u0637\\u064a \\u0628\\u062f\\u0627\\u064a\\u0629 \\\"\\u062a\\u0648\\u0627\\u0628\\u0644\\u064a\\u0629\\\" \\u062d\\u0627\\u062f\\u0629 \\u0648\\u0641\\u062e\\u0645\\u0629 \\u062a\\u0648\\u062d\\u064a \\u0628\\u0627\\u0644\\u0647\\u064a\\u0628\\u0629.<br>* \\u0642\\u0644\\u0628 \\u0627\\u0644\\u0639\\u0637\\u0631: \\u064a\\u0628\\u0631\\u0632 \\u0641\\u064a\\u0647 \\u062e\\u0634\\u0628 \\u0627\\u0644\\u0623\\u0631\\u0632 \\u0648\\u0627\\u0644\\u0628\\u0627\\u062a\\u0634\\u0648\\u0644\\u064a\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0636\\u064a\\u0641 \\u0644\\u0645\\u0633\\u0629 \\u062a\\u0631\\u0627\\u0628\\u064a\\u0629 \\u062e\\u0634\\u0628\\u064a\\u0629 \\u062a\\u0645\\u0646\\u062d \\u0627\\u0644\\u0639\\u0637\\u0631 \\u0637\\u0627\\u0628\\u0639\\u0627\\u064b \\u0630\\u0643\\u0648\\u0631\\u064a\\u0627\\u064b \\u0631\\u0632\\u064a\\u0646\\u0627\\u064b.<br>* \\u0627\\u0644\\u0642\\u0627\\u0639\\u062f\\u0629: \\u0647\\u064a \\u0633\\u0631 \\u0642\\u0648\\u0629 \\u0627\\u0644\\u0639\\u0637\\u0631\\u060c \\u062d\\u064a\\u062b \\u062a\\u0631\\u062a\\u0643\\u0632 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0639\\u0648\\u062f\\u060c \\u0627\\u0644\\u062c\\u0644\\u0648\\u062f (Leather)\\u060c \\u0648\\u0627\\u0644\\u0639\\u0646\\u0628\\u0631. \\u0647\\u0630\\u0647 \\u0627\\u0644\\u0642\\u0627\\u0639\\u062f\\u0629 \\u062a\\u062c\\u0639\\u0644 \\u0627\\u0644\\u0631\\u0627\\u0626\\u062d\\u0629 \\u062a\\u0628\\u062f\\u0648 \\\"\\u0645\\u062f\\u062e\\u0646\\u0629\\\" \\u0648\\u0641\\u062e\\u0645\\u0629 \\u062c\\u062f\\u0627\\u064b\\u060c \\u062a\\u0634\\u0628\\u0647 \\u0631\\u0627\\u0626\\u062d\\u0629 \\u0627\\u0644\\u0628\\u062e\\u0648\\u0631 \\u0627\\u0644\\u0645\\u0631\\u0643\\u0632.<br>### 2. \\u0627\\u0644\\u0623\\u062f\\u0627\\u0621 (\\u0627\\u0644\\u062b\\u0628\\u0627\\u062a \\u0648\\u0627\\u0644\\u0641\\u0648\\u062d\\u0627\\u0646)<br>* \\u0627\\u0644\\u062b\\u0628\\u0627\\u062a: \\u064a\\u062a\\u0645\\u064a\\u0632 \\\"\\u0627\\u0644\\u0628\\u0627\\u0632\\\" \\u0628\\u062b\\u0628\\u0627\\u062a \\u062c\\u0628\\u0627\\u0631\\u061b \\u0641\\u0647\\u0648 \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0637\\u0648\\u0631 \\\"\\u0627\\u0644\\u062b\\u0642\\u064a\\u0644\\u0629\\\" \\u0627\\u0644\\u062a\\u064a \\u062a\\u0644\\u062a\\u0635\\u0642 \\u0628\\u0627\\u0644\\u062c\\u0644\\u062f \\u0648\\u0627\\u0644\\u0645\\u0644\\u0627\\u0628\\u0633 \\u0644\\u0633\\u0627\\u0639\\u0627\\u062a \\u0637\\u0648\\u064a\\u0644\\u0629 \\u062c\\u062f\\u0627\\u064b (\\u062a\\u062a\\u062c\\u0627\\u0648\\u0632 12 \\u0633\\u0627\\u0639\\u0629).<br>* \\u0627\\u0644\\u0641\\u0648\\u062d\\u0627\\u0646: \\u0630\\u0648 \\u0641\\u0648\\u062d\\u0627\\u0646 \\u0648\\u0627\\u0633\\u0639 \\u062c\\u062f\\u0627\\u064b \\u0648\\u0642\\u0648\\u064a. \\u0647\\u0648 \\u0639\\u0637\\u0631 \\\"\\u0647\\u062c\\u0648\\u0645\\u064a\\\" \\u0628\\u0627\\u0645\\u062a\\u064a\\u0627\\u0632\\u060c \\u064a\\u0645\\u0644\\u0623 \\u0627\\u0644\\u0645\\u0643\\u0627\\u0646 \\u0628\\u0645\\u062c\\u0631\\u062f \\u062f\\u062e\\u0648\\u0644\\u0643\\u060c \\u0648\\u064a\\u062a\\u0631\\u0643 \\u0623\\u062b\\u0631\\u0627\\u064b \\u0639\\u0637\\u0631\\u064a\\u0627\\u064b \\u0642\\u0648\\u064a\\u0627\\u064b \\u062e\\u0644\\u0641\\u0643.<br>### 3. \\u0627\\u0644\\u0627\\u0646\\u0637\\u0628\\u0627\\u0639 \\u0627\\u0644\\u0639\\u0627\\u0645 \\u0648\\u0627\\u0644\\u0634\\u062e\\u0635\\u064a\\u0629<br>* \\u0627\\u0644\\u0631\\u0627\\u0626\\u062d\\u0629: \\u0631\\u0627\\u0626\\u062d\\u0629 \\u0631\\u0633\\u0645\\u064a\\u0629\\u060c \\u0642\\u0648\\u064a\\u0629\\u060c \\u0648\\u062f\\u0627\\u0643\\u0646\\u0629. \\u064a\\u063a\\u0644\\u0628 \\u0639\\u0644\\u064a\\u0647\\u0627 \\u0637\\u0627\\u0628\\u0639 \\u0627\\u0644\\u062c\\u0644\\u0648\\u062f \\u0648\\u0627\\u0644\\u0639\\u0648\\u062f\\u060c \\u0645\\u0645\\u0627 \\u064a\\u062c\\u0639\\u0644\\u0647\\u0627 \\u062a\\u0648\\u062d\\u064a \\u0628\\u0640 \\u0627\\u0644\\u063a\\u0645\\u0648\\u0636 \\u0648\\u0627\\u0644\\u0633\\u064a\\u0637\\u0631\\u0629.<br>* \\u0627\\u0644\\u0634\\u062e\\u0635\\u064a\\u0629: \\u064a\\u0646\\u0627\\u0633\\u0628 \\u0627\\u0644\\u0634\\u062e\\u0635\\u064a\\u0629 \\u0627\\u0644\\u0642\\u064a\\u0627\\u062f\\u064a\\u0629\\u060c \\u0627\\u0644\\u0648\\u0627\\u062b\\u0642\\u0629\\u060c \\u0648\\u0627\\u0644\\u062a\\u064a \\u062a\\u062d\\u0628 \\u0644\\u0641\\u062a \\u0627\\u0644\\u0623\\u0646\\u0638\\u0627\\u0631 \\u0628\\u0637\\u0631\\u064a\\u0642\\u0629 \\\"\\u0645\\u0647\\u064a\\u0628\\u0629\\\". \\u064a\\u0645\\u064a\\u0644 \\u0627\\u0644\\u0639\\u0637\\u0631 \\u0628\\u0634\\u0643\\u0644 \\u0643\\u0628\\u064a\\u0631 \\u062c\\u062f\\u0627\\u064b \\u0644\\u0644\\u062c\\u0627\\u0646\\u0628 \\u0627\\u0644\\u0631\\u062c\\u0627\\u0644\\u064a \\u0628\\u0633\\u0628\\u0628 \\u062d\\u062f\\u0629 \\u0627\\u0644\\u062c\\u0644\\u0648\\u062f \\u0648\\u0627\\u0644\\u0623\\u062e\\u0634\\u0627\\u0628 \\u0641\\u064a\\u0647.<br>### 4. \\u0645\\u062a\\u0649 \\u062a\\u0631\\u062a\\u062f\\u064a \\u0639\\u0637\\u0631 \\\"\\u0627\\u0644\\u0628\\u0627\\u0632\\\"\\u061f<br>* \\u0627\\u0644\\u0645\\u0646\\u0627\\u0633\\u0628\\u0627\\u062a: \\u0647\\u0648 \\u0639\\u0637\\u0631 \\u0627\\u0644\\u0645\\u0646\\u0627\\u0633\\u0628\\u0627\\u062a \\u0627\\u0644\\u0643\\u0628\\u0631\\u0649 \\u0648\\u0627\\u0644\\u0644\\u0642\\u0627\\u0621\\u0627\\u062a \\u0627\\u0644\\u0631\\u0633\\u0645\\u064a\\u0629 \\u0627\\u0644\\u0647\\u0627\\u0645\\u0629. \\u0644\\u0627 \\u064a\\u064f\\u0646\\u0635\\u062d \\u0628\\u0647 \\u0643\\u0639\\u0637\\u0631 \\u064a\\u0648\\u0645\\u064a \\u0644\\u0644\\u0645\\u0643\\u0627\\u062a\\u0628 \\u0627\\u0644\\u0636\\u064a\\u0642\\u0629 \\u0623\\u0648 \\u0627\\u0644\\u0635\\u064a\\u0641 \\u0627\\u0644\\u062d\\u0627\\u0631.<br>* \\u0627\\u0644\\u0641\\u0635\\u0648\\u0644: \\u064a\\u062a\\u0623\\u0644\\u0642 \\u0641\\u064a \\u0641\\u0635\\u0644 \\u0627\\u0644\\u0634\\u062a\\u0627\\u0621 \\u0648\\u0627\\u0644\\u0623\\u062c\\u0648\\u0627\\u0621 \\u0627\\u0644\\u0628\\u0627\\u0631\\u062f\\u0629 \\u062c\\u062f\\u0627\\u064b\\u061b \\u062d\\u064a\\u062b \\u062a\\u0628\\u0631\\u0632 \\u062d\\u0631\\u0627\\u0631\\u0629 \\u0627\\u0644\\u062a\\u0648\\u0627\\u0628\\u0644 \\u0648\\u062f\\u0641\\u0621 \\u0627\\u0644\\u062c\\u0644\\u0648\\u062f \\u0648\\u0627\\u0644\\u0639\\u0648\\u062f \\u0628\\u0634\\u0643\\u0644 \\u0645\\u062a\\u0632\\u0646 \\u0648\\u062c\\u0645\\u064a\\u0644.<br>* \\u0627\\u0644\\u062a\\u0648\\u0642\\u064a\\u062a: \\u0639\\u0637\\u0631 \\u0645\\u0633\\u0627\\u0626\\u064a \\u0628\\u0627\\u0645\\u062a\\u064a\\u0627\\u0632\\u060c \\u0648\\u064a\\u0635\\u0644\\u062d \\