621.<br>* \\u0633\\u0647\\u0648\\u0644\\u0629 \\u0627\\u0644\\u062a\\u0646\\u0638\\u064a\\u0641: \\u0627\\u0644\\u0635\\u0641\\u064a\\u062d\\u0629 \\u0645\\u0637\\u0644\\u064a\\u0629 \\u0628\\u0645\\u0627\\u062f\\u0629 \\u0645\\u0627\\u0646\\u0639\\u0629 \\u0644\\u0644\\u0627\\u0644\\u062a\\u0635\\u0627\\u0642 \\u0645\\u0645\\u0627 \\u064a\\u062c\\u0639\\u0644 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062a\\u0646\\u0638\\u064a\\u0641 \\u0633\\u0631\\u064a\\u0639\\u0629 \\u0648\\u0633\\u0647\\u0644\\u0629.<br><br>\\u0627\\u0644\\u0645\\u0648\\u0627\\u0635\\u0641\\u0627\\u062a \\u0627\\u0644\\u0641\\u0646\\u064a\\u0629:<br><br>* \\u0627\\u0644\\u0642\\u062f\\u0631\\u0629 \\u0627\\u0644\\u0643\\u0647\\u0631\\u0628\\u0627\\u0626\\u064a\\u0629: \\u062a\\u0635\\u0644 \\u0625\\u0644\\u0649 2200 \\u0648\\u0627\\u0637 \\u0643\\u062d\\u062f \\u0623\\u0642\\u0635\\u0649 \\u0644\\u0636\\u0645\\u0627\\u0646 \\u0627\\u0644\\u062a\\u0633\\u062e\\u064a\\u0646 \\u0627\\u0644\\u0633\\u0631\\u064a\\u0639.<br>* \\u0627\\u0644\\u062c\\u0647\\u062f \\u0627\\u0644\\u0643\\u0647\\u0631\\u0628\\u0627\\u0626\\u064a: \\u062a\\u0639\\u0645\\u0644 \\u0628\\u0646\\u0638\\u0627\\u0645 220-240 \\u0641\\u0648\\u0644\\u062a\\u060c \\u0628\\u062a\\u0631\\u062f\\u062f 50 \\u0647\\u0631\\u062a\\u0632.<br>* \\u0639\\u0646\\u0627\\u0635\\u0631 \\u0627\\u0644\\u062a\\u0633\\u062e\\u064a\\u0646: \\u0645\\u0632\\u0648\\u062f\\u0629 \\u0628\\u0648\\u0634\\u064a\\u0639\\u0629 \\u062a\\u0633\\u062e\\u064a\\u0646 (Heating coil) \\u0645\\u0646 \\u0627\\u0644\\u0641\\u0648\\u0644\\u0627\\u0630 \\u0627\\u0644\\u0645\\u0642\\u0627\\u0648\\u0645 \\u0644\\u0644\\u0635\\u062f\\u0623 \\u0639\\u0627\\u0644\\u064a \\u0627\\u0644\\u062c\\u0648\\u062f\\u0629.<br>* \\u0623\\u0628\\u0639\\u0627\\u062f \\u0627\\u0644\\u063a\\u0637\\u0627\\u0621: \\u0627\\u0631\\u062a\\u0641\\u0627\\u0639 \\u0627\\u0644\\u063a\\u0637\\u0627\\u0621 \\u0627\\u0644\\u062e\\u0627\\u0631\\u062c\\u064a 110 \\u0645\\u0644\\u0645\\u060c \\u