INSERT INTO `translations` VALUES (1,'App\\Model\\Attribute',1,'ar','name','الموديل'),(2,'App\\Model\\Product',13,'ar','name','خبازة متعددة الاستخدامات 3'),(3,'App\\Model\\Product',13,'ar','description','<p>المميزات الأساسية:<br><br>* متعددة الاستخدامات (3 في 1): مخصصة لصناعة الخبز العربي، الكريب، والبيتزا.<br>* حجم كبير: يبلغ قطر صفيحة الطهي 40 سم (ما يعادل 15 بوصة)، مما يسمح بتحضير أحجام عائلية.<br>* لوحة طهي من الجرانيت: تتميز بصفيحة \"Granite Plate\" بسماكة 2.5 ملم، مصنعة من الألمنيوم المصبوب (Die cast) لضمان توزيع الحرارة ومنع الالتصاق.<br>* تحكم كامل: مزودة بمنظم حرارة مزدوج (Double thermostats) للتحكم الدقيق في درجة الحرارة، بالإضافة إلى وجود مؤقت (Timer).<br>* نوافذ زجاجية: تحتوي على نوافذ جانبية لمراقبة نضج الطعام أثناء الطهي دون الحاجة لفتح الغطاء.<br>* سهولة التنظيف: الصفيحة مطلية بمادة مانعة للالتصاق مما يجعل عملية التنظيف سريعة وسهلة.<br><br>المواصفات الفنية:<br><br>* القدرة الكهربائية: تصل إلى 2200 واط كحد أقصى لضمان التسخين السريع.<br>* الجهد الكهربائي: تعمل بنظام 220-240 فولت، بتردد 50 هرتز.<br>* عناصر التسخين: مزودة بوشيعة تسخين (Heating coil) من الفولاذ المقاوم للصدأ عالي الجودة.<br>* أبعاد الغطاء: ارتفاع الغطاء الخارجي 110 ملم، والارتفاع الداخلي المفيد للطهي هو 90 ملم.<br>* الأمان: مقابض باردة الملمس (Cool touch handles) لسهولة وسلامة الاستخدام أثناء التشغيل.<br>ملاحظة إضافية: المنتج مصمم للتحميص السريع ودرجات الحرارة العالية (High Temp) للحصول على نتائج مخبوزات احترافية.</p>'),(4,'App\\Model\\Category',3,'ar','name','قلايات هوائية'),(5,'App\\Model\\Category',4,'ar','name','قدور كهربائية'),(6,'App\\Model\\Category',5,'ar','name','ثلاجات وفريزرات'),(7,'App\\Model\\Category',6,'ar','name','عجانات'),(8,'App\\Model\\Category',8,'ar','name','مكائن القهوة'),(9,'App\\Model\\Category',11,'ar','name','المكيفات'),(10,'App\\Model\\Category',2,'ar','name','أطقم الترامس'),(11,'App\\Model\\Product',14,'ar','name','product name here'),(12,'App\\Model\\Product',14,'ar','description','وصف المنتج'),(13,'App\\Model\\Attribute',2,'ar','name','الأبعاد'),(14,'App\\Model\\Attribute',3,'ar','name','اللون'),(15,'App\\Model\\Product',15,'ar','name','New Product2'),(16,'App\\Model\\Product',15,'ar','description','<p>بيسبيس</p>'),(17,'App\\Model\\Product',1,'ar','name','حقيبة نسائية جلد Women leather bag'),(18,'App\\Model\\Product',1,'ar','description','شامبو باليوريا بنسبة 3% للشعر من Elina Med، بتركيبة خفيفة ينظف الشعر و فروة الرأس بعمق ويمنح الشعر ترطيب مضاعف، يغذي الشعر من الجذور حتى الاطراف.<br><br><br>شامبو باليوريا بنسبة 3% للشعرمن الينا،بتركيبة خفيفة ينظف الشعر و فروة الرأس بعمق ويمنح الشعر ترطيب مضاعف، يغذي الشعر من الجذور حتى الاطراف.<br>مناسب لجميع انواع الشعر<br><br>'),(19,'App\\Model\\Category',12,'ar','name','أدوات المائدة'),(20,'App\\Model\\Product',16,'ar','name','قلاية هوائية إديسون، 1800 واط، 8 لتر، وعاء داخلي تيفال'),(21,'App\\Model\\Product',16,'ar','description','<h1 class=\"text-xl font-medium\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-gradient-from-position: ; --tw-gradient-via-position: ; --tw-gradient-to-position: ; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgba(59,130,246,.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; --tw-contain-size: ; --tw-contain-layout: ; --tw-con